{%- macro normalize_string_or_list(raw, field_name) -%}
  {%- if raw is none -%}
    {%- set result = [] -%}
  {%- elif raw is mapping -%}
    {{ exceptions.raise_compiler_error(field_name ~ " must be a list of strings or a string") }}
  {%- elif raw is string -%}
    {%- set result = [raw] -%}
  {%- elif raw is sequence -%}
    {%- set result = raw | list -%}
  {%- else -%}
    {{ exceptions.raise_compiler_error(field_name ~ " must be a list of strings or a string") }}
  {%- endif -%}
